#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, C;
    cin >> N >> K >> C;

    vector<long long> pref(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        long long x;
        cin >> x;
        pref[i] = pref[i - 1] + x;
    }

    const long long INF = (1LL << 60);
    int M = C + 1;
    vector<vector<long long>> ring(M, vector<long long>(K + 1, INF));
    ring[0][0] = 0;

    for (int i = 1; i <= N; ++i) {
        int curIdx = i % M;
        vector<long long>& cur = ring[curIdx];
        cur[0] = 0;

        int maxJ = min(K, i / C);
        int prevMax = min(K, (i - 1) / C);
        vector<long long>& prev = ring[(i - 1) % M];

        long long w = 0;
        if (i >= C) w = pref[i] - pref[i - C];

        for (int j = 1; j <= maxJ; ++j) {
            long long val = INF;

            if (j <= prevMax) val = prev[j];

            if (i >= C) {
                long long cand = ring[(i - C) % M][j - 1] + w;
                if (cand < val) val = cand;
            }

            cur[j] = val;
        }
    }

    long long minCovered = ring[N % M][K];
    cout << pref[N] - minCovered << '\n';

    return 0;
}
